effect.shader:
const float PI = 3.14159265;
void main(){
    vec2 dir=normalize(vec2(1.0,1.0));
    float pos=dot(acScreenNorm,dir);
    float curlAt=mix(1.42, -radius*PI, amount);
    vec2 uv=acScreenNorm;
    vec4 col;
    if(pos>curlAt+radius*PI){
        col=texture2DCv(inputImg.texture, uv);
    } else if(pos>curlAt){
        float ph=(pos-curlAt)/radius;
        float off=radius*(ph - sin(ph));
        uv -= dir*off*2.0;
        col=texture2DCv(inputImg.texture, uv);
        col.rgb *= 0.6+0.4*sin(ph);
    } else {
        float back=curlAt-pos;
        uv += dir*back*1.0;
        col=texture2DCv(inputImg.texture, uv);
        col.rgb *= 0.35;
    }
    gl_FragColor=col;
}
